SELECT TOP 50 CASE state WHEN 'Active' THEN 'active' WHEN 'Closed' THEN 'churned' WHEN 'Hold' THEN 'suspended' END AS [customer_status], AVG(FLOOR(ABS(CAST(credit_limit AS NUMERIC(38, 6)) / CAST(5000 AS NUMERIC(38, 6))) + 0.5) * SIGN(CAST(credit_limit AS NUMERIC(38, 6)) / CAST(5000 AS NUMERIC(38, 6))) * 5000) AS [credit_limit_r5000_avg] FROM accounts WHERE opened_at >= CAST('2026-08-25T15:00:00.000000' AS DATETIME2) AND opened_at < CAST('2026-11-25T15:00:00.000000' AS DATETIME2) GROUP BY CASE state WHEN 'Active' THEN 'active' WHEN 'Closed' THEN 'churned' WHEN 'Hold' THEN 'suspended' END